html,
body {
  margin: 0;
  padding: 0;
  height: 100%;
  color: var(--vscode-editor-foreground);
  background: var(--vscode-editor-background);
  font-family:
    "LINE Seed JP",
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    "Hiragino Sans",
    "Yu Gothic UI",
    "Meiryo",
    system-ui,
    sans-serif;
  font-size: var(--vscode-font-size);
}
body {
  --md-surface: var(--vscode-editor-background);
  --md-paper: var(--vscode-editor-background);
  --md-paper-border: var(--vscode-panel-border, rgba(128,128,128,0.25));
  --md-toolbar-bg: color-mix(in oklab, var(--vscode-editor-background) 92%, black 8%);
